{
    u32 i;
    for (i = 0; i < 12; i++) table[i] = entries[i];
}

static inline void init_tail(TailState* tail)
{
    tail->x = lbl_80651540;
    tail->y = lbl_80651540;
    tail->z = lbl_80651544;
}

void fn_801FD318(void)
{
    State* state = &lbl_8063EA00;
