typedef unsigned char u8;
typedef unsigned int u32;

typedef struct TailState {
    float x;
    float y;
    float z;
} TailState;

typedef struct Table { void* pointers[12]; } Table;
typedef struct State {
    Table table;
    u8 entries[12][124];
    TailState tail;
} State;

extern State lbl_8063EA00;
extern u32 lbl_8064D7C8;
extern u32 lbl_8064D7CC;
extern void* lbl_8064D7D0;
extern const float lbl_80651540;
extern const float lbl_80651544;
extern void* memset(void*, int, unsigned int);

static inline void init_table(Table* table, u8 entries[][124])
{
    u32 i;
    for (i = 0; i < 12; i++) table->pointers[i] = entries[i];
}

static inline void init_tail(TailState* tail, float x, float y, float z)
{
    tail->x = x;
    tail->y = y;
    tail->z = z;
}

void fn_801FD318(void)
{
    State* state = &lbl_8063EA00;
    u32 i;

    memset(state->entries, 0, sizeof(state->entries));
    init_table(&state->table, state->entries);
    lbl_8064D7D0 = state->entries;
    lbl_8064D7CC = 0;
    lbl_8064D7C8 = 0x10000;
    init_tail(&state->tail, lbl_80651540, lbl_80651540, lbl_80651544);
}

