    init_table(state->pointers, state->entries[0], 124);
    lbl_8064D7D0 = state->entries;
    lbl_8064D7CC = 0;
    lbl_8064D7C8 = 0x10000;
    state->tail.x = lbl_80651540;
    state->tail.y = lbl_80651540;
    state->tail.z = lbl_80651544;
}

